def data_extract(infilename,outdataname,skipline,tcolum,dcolum,flag1,flag2):
    """
    計測器のcsvデータから、条件付けして分布を生成するためのデータを抽出する
    infilename:dirを指定した場合、指定した拡張子に一致した全てのファイルを読み取る
    skipline:無視する行数int
    tcolum:トリガーコラム（配列で指定）
    dcolum:抽出データのコラム（配列で複数抽出可能）
    flag1:トリガー成立条件
    flag2:データ抽出条件
    flag1=0:コラムtcolum[0]の値がtcolum[1]と一致した場合（前回未成立が成立した時点）
    flag1=1:コラムtcolum[0]の値がtcolum[1]より大きい場合（前回未成立が成立した時点）
    flag1=2:コラムtcolum[0]の値がtcolum[1]より小さい場合（前回未成立が成立した時点）
    flag2=0:トリガー成立時の所定位置のデータを抽出
    flag2=1:トリガー成立時の所定位置のデータ（走行距離など累積値）の前回値との差を抽出（トリガーの頻度抽出）
    flag2=2:トリガー成立時と前回値の間の車速を積分して区間距離を抽出（トリガーの頻度抽出）dcolum[0]が速度、dcolum[1]がサンプル時間
    """
    #fp = FontProperties(fname=r'C:\Windows\Fonts\msgothic.ttc',size=fs)
    #plt.rcParams["font.size"] = fs
    if os.path.isfile(infilename):
        dirname=0
        filename=os.path.splitext(infilename)
    elif os.path.isdir(infilename):
        dirname=1
        path=infilename
        filename=os.path.splitext(glob.glob(path+'/*.csv')[0])
        if filename==[]:
            filename=os.path.splitext(glob.glob(path+'/*.xlsx')[0])
        elif filename==[]:
            filename=os.path.splitext(glob.glob(path+'/*.txt')[0])
    sht=filename[0]#エクセルのシート名
    outfilename=os.path.splitext(outdataname)
    fg=0
    colum=tcolum.append(dcolum[0])
    flag0=0#:cp932,1:指定せず
    if filename[1]=='.csv':
        if dirname==0:
            #breakpoint()
            if flag0==0:
                df = pd.read_csv(infilename,usecols=colum,skiprows=skipline,na_values=999,encoding='cp932')
            else:
                df = pd.read_csv(infilename,usecols=colum,skiprows=skipline,na_values=999)
            dt = df.values
        elif dirname==1:
            dt=[]
            allFiles = glob.glob(path+'/*.csv')
            for file_ in allFiles:
                if flag0==0:
                    df = pd.read_csv(file_,usecols=colum,skiprows=skipline,na_values=999,encoding='cp932')
                else:
                    df = pd.read_csv(file_,usecols=colum,skiprows=skipline,na_values=999)
                dt.extend(df.values)
        
    elif filename[1]=='.xlsx':
        sht='Sheet1'
        if dirname==0:
            
            df = pd.read_excel(infilename,usecols=colum,skiprows=skipline,sheet_name=sht,na_values=999)
            dt = df.values
        elif dirname==1:
            dt=[]
            allFiles = glob.glob(path+'/*xlsx')
            for file_ in allFiles:
                df = pd.read_excel(file_,usecols=colum,skiprows=skipline,sheet_name=sht,na_values=999)
                dt.extend(df.values)
    elif filename[1]=='.txt':
        if dirname==0:
            if flag0==0:
                df = pd.read_table(infilename,usecols=colum,skiprows=skipline,na_values=999,encoding='cp932')
            else:
                df = pd.read_table(infilename,usecols=colum,skiprows=skipline,na_values=999)
            dt = df.values
        elif dirname==1:
            fg=1
            dt=[]
            allFiles = glob.glob(path+'/*txt')
            for file_ in allFiles:
                if flag0==0:
                    df = pd.read_table(file_,usecols=colum,skiprows=skipline,na_values=999,encoding='cp932')
                else:
                    df = pd.read_table(file_,usecols=colum,skiprows=skipline,na_values=999)
                dt.extend(df.values)
    data=dt
    pu_data=[]
    col=np.array(dcolum)
    tmp=col.argsort()
    t_data=[]
    if flag1==0 or flag1==1:
        lasttrg=tcolum[1]-1
    elif flag1==2:
        #lasttrg=tcolum[1]+1
        lasttrg=tcolum[1]
    lastpu_data=0
    ruiseki=0
    for i in range(len(data)):
        #xx=[]
        #for j in range(len(tmp)):
        #    xx.append(data[i][tmp[j]])
        #t_data.append(data[i][tcolum[0]])#トリガーデータの列
        #if (flag1 == 0 and data[i][0] == data[i][1] and lasttrg != data[i][1]) or (flag1 == 1 and data[i][0]>=data[i][1] and lasttrg < data[i][1]) or (flag1 == 2 and data[i][0]<=data[i][1] and lasttrg > data[i][1]):
        if (flag1 == 0 and data[i][tcolum[0]] == tcolum[1] and lasttrg != tcolum[1]) or (flag1 == 1 and data[i][tcolum[0]]>tcolum[1] and lasttrg <= tcolum[1]) or (flag1 == 2 and data[i][tcolum[0]]<tcolum[1] and lasttrg >= tcolum[1]):
            
            if flag2 == 0:
                pu_data.append(data[i][dcolum[0]])#抽出データの列
            elif flag2 == 1:
                pu_data.append(data[i][dcolum[0]]-lastpu_data)
                lastpu_data=data[i][dcolum[0]]
            elif flag2 == 2:
                #
                pu_data.append(ruiseki)
                ruiseki=0
        lasttrg=data[i][tcolum[0]]
        if flag2 ==2:
            ruiseki += data[i][dcolum[0]]*dcolum[1]
    #
    #breakpoint()
    df=pd.DataFrame(pu_data)
    df.to_csv(outdataname)
    
    

