    list0 = abs(cp.array([xpara[0]])-zpara0)#0.36089158058166504
    #xdyに一番近いラベルlab*0と2番目に近いラベルlab*1を求める、xparaのラベル
    lab000 = [cp.where(list0[i] == cp.sort(list0[i])[0])[0][0] for i in range(zn0t)]#一番近い
    lab010 = [cp.where(list0[i] == cp.sort(list0[i])[1])[0][0] for i in range(zn0t)]#2番目に近い
    #大きさがlab00<lab01の順に並べる
