def cal_prdquad_b(dim,dt,dtb,zaxb,saxisb,psaxisb,divzb,saxbmin,saxbmax,yaxb,pyaxb,gpu=0):
    #完成するまで 
    gpu=0
    #b:割り算sy座標の第3象限
    kspn = 2
    ycutmax = yaxb[-1]-saxbmin
    ycutmin = yaxb[0]-saxbmax
    span = ycutmax-ycutmin
    if dim == 1:
        divspn = kspn*int(max(1,span//(dt[0]**0.5)))#y切片の分割数
    elif dim == 2:
        divspn = kspn*int(max(1,span//((dt[0]**2+dt[1]**2)**0.5)))
    elif dim == 3:
        divspn = kspn*int(max(1,span//((dt[0]**2+dt[1]**2+dt[2]**2)**0.5)))#y切片の分割数
    #
    #print(ycutmin,ycutmax,divspn,dt,span,saxbmin,saxbmax,yaxb[0][0],yaxb[0][-1])
    ycut = np.linspace(ycutmin,ycutmax,divspn)#y切片の配列
    dspn = span/(divspn-1)#y切片の分割幅
    xbase0 = (-ycut.reshape(1,divspn)-((ycut.reshape(1,divspn))**2+zaxb.reshape(divzb,1)*4)**0.5)/2
    #xbase0 = (-ycut.reshape(1,divspn)-((ycut.reshape(1,divspn))**2-zaxb.reshape(divzb,1)*4)**0.5)/2
    ybase0 = (ycut.reshape(1,divspn)-((ycut.reshape(1,divspn))**2+zaxb.reshape(divzb,1)*4)**0.5)/2
    if dim == 1:
        xbase1 = (-ycut.reshape(1,divspn)-((ycut.reshape(1,divspn))**2+(zaxb+dt[0]).reshape(divzb,1)*4)**0.5)/2
        #xbase1 = (-ycut.reshape(1,divspn)-((ycut.reshape(1,divspn))**2+(zaxb+dt[0]).reshape(divzb,1)*4)**0.5)/2
        ybase1 = (ycut.reshape(1,divspn)-((ycut.reshape(1,divspn))**2+(zaxb+dt[0]).reshape(divzb,1)*4)**0.5)/2
    else:
        xbase1 = (-ycut.reshape(1,divspn)-((ycut.reshape(1,divspn))**2+(zaxb+dtb).reshape(divzb,1)*4)**0.5)/2
        #xbase1 = (-ycut.reshape(1,divspn)-((ycut.reshape(1,divspn))**2+(zaxb+dtb).reshape(divzb,1)*4)**0.5)/2
        ybase1 = (ycut.reshape(1,divspn)-((ycut.reshape(1,divspn))**2+(zaxb+dtb).reshape(divzb,1)*4)**0.5)/2
    #xib,xtmp = np.split(xbase,[-1],0)
    xij,xtmp = np.split(xbase0,[-1],1)
    #xtmp,xi1b = np.split(xbase,[1],0)
    xtmp,xi1j1 = np.split(xbase1,[1],1)
    xtmp,xij1 = np.split(xbase0,[1],1)
    xi1j,xtmp = np.split(xbase1,[-1],1)
    #yib,ytmp = np.split(ybase,[-1],0)
    yij,ytmp = np.split(ybase0,[-1],1)
    #ytmp,yi1b = np.split(ybase,[1],0)
    ytmp,yi1j1 = np.split(ybase1,[1],1)
    ytmp,yij1 = np.split(ybase0,[1],1)
    yi1j,ytmp = np.split(ybase1,[-1],1)
    if dim == 1:
        test2=0
    else:
        test2 = 1
    if test2 == 1:
        xlist0 = np.array([xij,xi1j,xij1,xi1j1])
        ylist0 = np.array([yij,yi1j,yij1,yi1j1])
        xlist = np.sort(xlist0,axis=0)
        ylist = np.sort(ylist0,axis=0)
        spxij = xlist[3]-xlist[0]
        spyij = ylist[3]-ylist[0]
        sqxija = xlist[3]-xlist[2]
        sqxijb = xlist[1]-xlist[0]
        sqyija = ylist[3]-ylist[2]
        sqyijb = ylist[1]-ylist[0]
    else:
        spxij = xij-xi1j1
        spyij = yij1-yi1j
        #sqxij = xij-xi1j1
        #sqyij = yi1j-yij1
        sqxija = xij1-xi1j1
        sqxijb = xij-xi1j
        sqyija = yij1-yi1j1
        sqyijb = yij-yi1j
    darea = spxij*spyij-(sqxija*sqyija+ sqxijb*sqyijb+(spxij-sqxija)*(spyij-sqyijb)+(spxij-sqxijb)*(spyij-sqyija))/2
    #darea = (abs(spxij*spyij)+abs(sqxij*sqyij))/2
    xmean = (xij+xij1)/2
    ymean = (yij+yij1)/2
    case = 1
