def cal_divquad_b(dim,dt,dtb,zaxb,saxisb,psaxisb,divzb,saxbmin,saxbmax,yaxb,pyaxb,gpu=0):
    #完成するまで 
    gpu=0
    #b:割り算sy座標の第3象限
    kspn = 2
    scutmax = (saxbmax+yaxb[-1])
    scutmin = (saxbmin+yaxb[0])
    span = scutmax-scutmin
    if dim == 1:
        divspn = kspn*int(max(1,span//(dt[0]**0.5)))#y切片の分割数
    elif dim == 2:
        divspn = kspn*int(max(1,span//((dt[0]**2+dt[1]**2)**0.5)))
    elif dim == 3:
        divspn = kspn*int(max(1,span//((dt[0]**2+dt[1]**2+dt[2]**2)**0.5)))#y切片の分割数
    #
    #print(scutmin,scutmax,divspn,dt,span,saxbmin,saxbmax,yaxb[0][0],yaxb[0][-1])
    scut = np.linspace(scutmin,scutmax,divspn)#y切片の配列
    dspn = span/(divspn-1)#y切片の分割幅
    xbase0 = scut.reshape(1,divspn)/(1+1/zaxb.reshape(divzb,1))
    ybase0 = scut.reshape(1,divspn)/(1+zaxb.reshape(divzb,1))
    if dim == 1:
        xbase1 = scut.reshape(1,divspn)/(1+1/(zaxb+dt[0]).reshape(divzb,1))
        ybase1 = scut.reshape(1,divspn)/(1+(zaxb+dt[0]).reshape(divzb,1))
    else:
    
        xbase1 = scut.reshape(1,divspn)/(1+1/(zaxb+dtb).reshape(divzb,1))
        ybase1 = scut.reshape(1,divspn)/(1+(zaxb+dtb).reshape(divzb,1))
    #xib,xtmp = np.split(xbase,[-1],0)
    xij,xtmp = np.split(xbase0,[-1],1)
    #xtmp,xi1b = np.split(xbase,[1],0)
    xtmp,xi1j1 = np.split(xbase1,[1],1)
    xtmp,xij1 = np.split(xbase0,[1],1)
    xi1j,xtmp = np.split(xbase1,[-1],1)
    #yib,ytmp = np.split(ybase,[-1],0)
    yij,ytmp = np.split(ybase0,[-1],1)
    #ytmp,yi1b = np.split(ybase,[1],0)
    ytmp,yi1j1 = np.split(ybase1,[1],1)
    ytmp,yij1 = np.split(ybase0,[1],1)
    yi1j,ytmp = np.split(ybase1,[-1],1)
    test2 = 1
    if test2 == 1:
        xlist0 = np.array([xij,xi1j,xij1,xi1j1])
        ylist0 = np.array([yij,yi1j,yij1,yi1j1])
        xlist = np.sort(xlist0,axis=0)
        ylist = np.sort(ylist0,axis=0)
        spxij = xlist[3]-xlist[0]
        spyij = ylist[3]-ylist[0]
        sqxija = xlist[3]-xlist[2]
        sqxijb = xlist[1]-xlist[0]
        sqyija = ylist[3]-ylist[2]
        sqyijb = ylist[1]-ylist[0]
    else:
        spxij = xij1-xi1j
        spyij = yi1j1-yij
        #sqxij = xi1j1-xij
        #sqyij = yij1-yi1j
        sqxija = xij1-xi1j1
        sqxijb = xij-xi1j
        sqyija = yi1j1-yij1
        sqyijb = yi1j-yij
    darea = spxij*spyij-(sqxija*sqyija+ sqxijb*sqyijb+(spxij-sqxija)*(spyij-sqyijb)+(spxij-sqxijb)*(spyij-sqyija))/2
    #darea = (abs(spxij*spyij)+abs(sqxij*sqyij))/2
    xmean = (xij+xij1)/2
    ymean = (yij+yij1)/2
    case = 1
    if case == 0:
        pxflatten = interpol_1d_np(saxisp,psaxisp,[xmean.flatten()])#saxnとsaxpはxの1次元配列、xbaseはijの2次元アレー、結果はijの2次元アレー
        pxmesh = pxflatten[1].reshape(divzp,divspn-1)
        pyflatten = interpol_1d_np(saxisp,psaxisp,[ymean.flatten()])
        pymesh = pyflatten[1].reshape(divzp,divspn-1)
    elif case == 1:
        px1 = np.array([])
        py1 = np.array([])
        inp = 0
        for i in range(divzb):
            #px0 = interpol_1d_np(saxisp[i],psaxisp[i],[xmean[i]])##
            if dim == 1:
                #
                px0 = interpol_1d_np(saxisb,psaxisb,[xmean[i]])##
            else:
                
                if type(psaxisb[i]) == int or len(saxisb[i]) <= 1:# or xmean[i][0] < 0: 
                    px0 = [0,np.zeros(divspn-1)]
                elif divspn == 0:
                    px0 = [0,0]
                else:
                    if inp == 0:
                        if gpu == 0:
                            px0 = interpol_1d_np([saxisb[i]],[saxisb[i],psaxisb[i]],[xmean[i]])#
                        elif gpu == 1:
                            px0 = interpol_1d_cp([saxisb[i]],[saxisb[i],psaxisb[i]],[xmean[i]])#
                    elif inp == 1:
                        funp = interpolate.Rbf(saxisb[i],psaxisb[i],function='linear', smooth=0)
                        px0 = [0,funp(xmean[i])]
            px1 = np.append(px1,px0[1])
            
            if divspn == 0:
                py0 = [0,0]
            else:
                py0 = interpol_1d_np([yaxb],[yaxb,pyaxb],[ymean[i]])
            py1 = np.append(py1,py0[1])
        pxmesh = px1.reshape(divzb,divspn-1)##2次元の場合、これがおかしくなる、対応を検討する
        pymesh = py1.reshape(divzb,divspn-1)
    if dim == 1:
        #flag = np.array([[1 if xmean[j][i] >= max(0,saxbmin) and xmean[j][i] <= saxbmax and ymean[j][i] >= max(0,yaxb[0][0]) and ymean[j][i] <= yaxb[0][-1] else 0 for i in range(divspn-1)]for j in range(divza)])
        #pz_tmp = flag*pxmesh*pymesh*darea/dt[0]
        pz_tmp = pxmesh*pymesh*darea/dt[0]
    elif dim == 2:
        #flag = np.array([[1 if xij[j][i] >= max(0,min_s[j]) and xij[j][i] <= max_s[j] and yij[j][i] >= max(0,ymin[0]) and yij[j][i] <= ymax[0] and\
        #                   np.sign(zf[0][j]) == np.sign(max_sx[j]) and np.sign(zf[1][j]) == np.sign(max_sy[j]) else 0 for i in range(divspn-1)]for j in range(divza)])
        pz_tmp = pxmesh*pymesh*darea/(dtb.reshape(divzb,1)*np.ones((1,divspn-1)))
        zi_tmp = zaxb.reshape(divzb,1)*np.ones((1,divspn-1))
        #pz_tmp = flag*pz_tmp*xij/zi_tmp#flagの影響は1％
        pz_tmp = pz_tmp*xmean/zi_tmp
    elif dim == 3:
        #flag = np.array([[1 if xij[j][i] >= max(0,min_s[j]) and xij[j][i] <= max_s[j] and yij[j][i] >= max(0,ymin[0]) and yij[j][i] <= ymax[0] and \
        #                  np.sign(zf[0][j]) == np.sign(max_sx[j]) and np.sign(zf[1][j]) == np.sign(max_sy[j]) and np.sign(zf[2][j]) == np.sign(max_sz[j])\
        #                  else 0 for i in range(divspn-1)]for j in range(divzp)])
        pz_tmp = pxmesh*pymesh*darea/(dtb.reshape(divzb,1)*np.ones((1,divspn-1)))
        zi_tmp = zaxb.reshape(divzb,1)*np.ones((1,divspn-1))
        #pz_tmp = flag*pz_tmp*(xij/zi_tmp)**2
        pz_tmp = pz_tmp*(xmean/zi_tmp)**2
    pz1 = np.sum(pz_tmp,axis=1)
    return pz1

def cal_divquad_c(dim,dt,dtc,zaxc,saxisc,psaxisc,divzc,saxcmin,saxcmax,yaxc,pyaxc,gpu=0):
    #完成するまで 
    gpu=0
    #c:割り算sy座標の第2象限
    kspn = 2
    scutmax = saxcmax-yaxc[0]
    scutmin = saxcmin-yaxc[-1]
    span = saxcmax-saxcmin
    if dim == 1:
        divspn = kspn*int(max(1,span//(dt[0]**0.5)))#y切片の分割数
    elif dim == 2:
        divspn = kspn*int(max(1,span//((dt[0]**2+dt[1]**2)**0.5)))#y切片の分割数
    elif dim == 3:
        divspn = kspn*int(max(1,span//((dt[0]**2+dt[1]**2+dt[2]**2)**0.5)))#y切片の分割数
    #print(scutmax,scutmin,divspn,span,dt[0])#-20.0 -125.0 -372 -55.0 0.08802308802308802
    scut = np.linspace(scutmax,scutmin,divspn)#y切片の配列
    dspn = span/(divspn-1)#y切片の分割幅
    #
    if dim == 1:
        xbase0 = scut.reshape(1,divspn)/(1-1/zaxc.reshape(divzc,1))
        ybase0 = scut.reshape(1,divspn)/(zaxc.reshape(divzc,1)-1)
        xbase1 = scut.reshape(1,divspn)/(1-1/(zaxc+dt[0]).reshape(divzc,1))
        ybase1 = scut.reshape(1,divspn)/((zaxc+dt[0]).reshape(divzc,1)-1)
    else:
        xbase0 = scut.reshape(1,divspn)/(1+1/zaxc.reshape(divzc,1))
        ybase0 = -1*scut.reshape(1,divspn)/(zaxc.reshape(divzc,1)+1)
        xbase1 = scut.reshape(1,divspn)/(1+1/(zaxc+dtc).reshape(divzc,1))
        ybase1 = -1*scut.reshape(1,divspn)/((zaxc+dtc).reshape(divzc,1)+1)

    #xib,xtmp = np.split(xbase,[-1],0)
    xij,xtmp = np.split(xbase0,[-1],1)
    #xtmp,xi1b = np.split(xbase,[1],0)
    xtmp,xi1j1 = np.split(xbase1,[1],1)
    xtmp,xij1 = np.split(xbase0,[1],1)
    xi1j,xtmp = np.split(xbase1,[-1],1)
    #yib,ytmp = np.split(ybase,[-1],0)
    yij,ytmp = np.split(ybase0,[-1],1)
    #ytmp,yi1b = np.split(ybase,[1],0)
    ytmp,yi1j1 = np.split(ybase1,[1],1)
    ytmp,yij1 = np.split(ybase0,[1],1)
    yi1j,ytmp = np.split(ybase1,[-1],1)
    test2 = 1
    if test2 == 1:
        xlist0 = np.array([xij,xi1j,xij1,xi1j1])
        ylist0 = np.array([yij,yi1j,yij1,yi1j1])
        xlist = np.sort(xlist0,axis=0)
        ylist = np.sort(ylist0,axis=0)
        spxij = xlist[3]-xlist[0]
        spyij = ylist[3]-ylist[0]
        sqxija = xlist[3]-xlist[2]
        sqxijb = xlist[1]-xlist[0]
        sqyija = ylist[3]-ylist[2]
        sqyijb = ylist[1]-ylist[0]
    else:
        spxij = xi1j-xij1
        spyij = yi1j1-yij
        #sqxij = xi1j1-xij
        #sqyij = yij1-yi1j
        sqxija = xi1j1-xij1
        sqxijb = xi1j-xij
        sqyija = yi1j1-yij1
        sqyijb = yi1j-yij
    darea = spxij*spyij-(sqxija*sqyija+ sqxijb*sqyijb+(spxij-sqxija)*(spyij-sqyijb)+(spxij-sqxijb)*(spyij-sqyija))/2
    #darea = (abs(spxij*spyij)+abs(sqxij*sqyij))/2
    xmean = (xij+xij1)/2
    ymean = (yij+yij1)/2
    px1 = np.array([])
    py1 = np.array([])
    inp = 0
    for i in range(divzc):
        if dim == 1:
            px0 = interpol_1d_np(saxisc,psaxisc,[xmean[i]])
        else:
            if type(psaxisc[i]) == int or len(saxisc[i]) <= 1:
                px0 = [0,np.zeros(divspn-1)]
            elif divspn == 0:
                px0 = [0,0]
            else:
                if inp == 0:
                    if gpu == 0:
                        px0 = interpol_1d_np([saxisc[i]],[saxisc[i],psaxisc[i]],[xmean[i]])
                    elif gpu == 1:
                        px0 = interpol_1d_cp([saxisc[i]],[saxisc[i],psaxisc[i]],[xmean[i]])
                elif inp == 1:
                    funp = interpolate.Rbf(saxisc[i],psaxisc[i],function='linear', smooth=0)
                    px0 = [0,funp(xmean[i])]
        px1 = np.append(px1,px0[1])
        py0 = interpol_1d_np([yaxc],[yaxc,pyaxc],[ymean[i]])
        py1 = np.append(py1,py0[1])
    pxmesh = px1.reshape(divzc,divspn-1)
    pymesh = py1.reshape(divzc,divspn-1)
    if dim == 1:
        pz_tmp = pxmesh*pymesh*darea/dt[0]
    elif dim == 2:
        #flag = np.array([[1 if xij[j][i] >= max(0,min_s[j]) and xij[j][i] <= max_s[j] and yij[j][i] >= ymin[0] and yij[j][i] <= min(0,ymax[0]) and \
        #                  np.sign(zf[0][j]) != np.sign(max_sx[j]) and np.sign(zf[1][j]) != np.sign(max_sy[j]) else 0 for i in range(divspn-1)]for j in range(divzn)])
        pz_tmp = pxmesh*pymesh*darea/(dtc.reshape(divzc,1)*np.ones((1,divspn-1)))
        #zi_tmp = zaxn.reshape(divzn,1)*np.ones((1,divspn-1))
        zi_tmp = abs(zaxc.reshape(divzc,1))*np.ones((1,divspn-1))
        #pz_tmp = flag*pz_tmp*abs(xij)/zi_tmp
        #pz_tmp = pz_tmp*abs(xij)/zi_tmp
        pz_tmp = pz_tmp*abs(xmean)/zi_tmp
    elif dim == 3:
        #flag = np.array([[1 if xij[j][i] >= max(0,min_s[j]) and xij[j][i] <= max_s[j] and yij[j][i] >= ymin[0] and yij[j][i] <= min(0,ymax[0]) and \
        #                  np.sign(zf[0][j]) != np.sign(max_sx[j]) and np.sign(zf[1][j]) != np.sign(max_sy[j]) and np.sign(zf[2][j]) != np.sign(max_sz[j]) \
        #                  else 0 for i in range(divspn-1)]for j in range(divzc)])
        pz_tmp = pxmesh*pymesh*darea/(dtc.reshape(divzc,1)*np.ones((1,divspn-1)))
        zi_tmp = zaxc.reshape(divzc,1)*np.ones((1,divspn-1))
        pz_tmp = pz_tmp*(xij/zi_tmp)**2
        #pz_tmp = flag*pz_tmp*(xij/zi_tmp)**2
    pz2 = np.sum(pz_tmp,axis=1)
    return pz2

def cal_divquad_d(dim,dt,dtd,zaxd,saxisd,psaxisd,divzd,saxdmin,saxdmax,yaxd,pyaxd,gpu=0):
    #完成するまで 
    gpu=0
    #d:割り算sy座標の第4象限
    kspn = 2
    scutmax = saxdmax-yaxd[0]
    scutmin = saxdmin-yaxd[-1]
    span = scutmax-scutmin
    if dim == 1:
        divspn = kspn*int(max(1,span//(dt[0]**0.5)))#y切片の分割数
    elif dim == 2:
        divspn = kspn*int(max(1,span//((dt[0]**2+dt[1]**2)**0.5)))#y切片の分割数
    elif dim == 3:
        divspn = kspn*int(max(1,span//((dt[0]**2+dt[1]**2+dt[2]**2)**0.5)))#y切片の分割数
    #print(scutmax,scutmin,divspn,span,dt[0])#-20.0 -125.0 -372 -55.0 0.08802308802308802
    scut = np.linspace(scutmax,scutmin,divspn)#y切片の配列
    dspn = (scutmax-scutmin)/(divspn-1)#y切片の分割幅
    #
    if dim == 1:
        xbase0 = scut.reshape(1,divspn)/(1-1/zaxd.reshape(divzd,1))
        ybase0 = scut.reshape(1,divspn)/(zaxd.reshape(divzd,1)-1)
        xbase1 = scut.reshape(1,divspn)/(1-1/(zaxd+dt[0]).reshape(divzd,1))
        ybase1 = scut.reshape(1,divspn)/((zaxd+dt[0]).reshape(divzd,1)-1)
    else:
        xbase0 = scut.reshape(1,divspn)/(1+1/zaxd.reshape(divzd,1))
        ybase0 = -1*scut.reshape(1,divspn)/(zaxd.reshape(divzd,1)+1)
        xbase1 = scut.reshape(1,divspn)/(1+1/(zaxd+dtd).reshape(divzd,1))
        ybase1 = -1*scut.reshape(1,divspn)/((zaxd+dtd).reshape(divzd,1)+1)

    #xib,xtmp = np.split(xbase,[-1],0)
    xij,xtmp = np.split(xbase0,[-1],1)
    #xtmp,xi1b = np.split(xbase,[1],0)
    xtmp,xi1j1 = np.split(xbase1,[1],1)
    xtmp,xij1 = np.split(xbase0,[1],1)
    xi1j,xtmp = np.split(xbase1,[-1],1)
    #yib,ytmp = np.split(ybase,[-1],0)
    yij,ytmp = np.split(ybase0,[-1],1)
    #ytmp,yi1b = np.split(ybase,[1],0)
    ytmp,yi1j1 = np.split(ybase1,[1],1)
    ytmp,yij1 = np.split(ybase0,[1],1)
    yi1j,ytmp = np.split(ybase1,[-1],1)
    test2 = 1
    if test2 == 1:
        xlist0 = np.array([xij,xi1j,xij1,xi1j1])
        ylist0 = np.array([yij,yi1j,yij1,yi1j1])
        xlist = np.sort(xlist0,axis=0)
        ylist = np.sort(ylist0,axis=0)
        spxij = xlist[3]-xlist[0]
        spyij = ylist[3]-ylist[0]
        sqxija = xlist[3]-xlist[2]
        sqxijb = xlist[1]-xlist[0]
        sqyija = ylist[3]-ylist[2]
        sqyijb = ylist[1]-ylist[0]
    elif test2 == 0:
        spxij = xij-xi1j1
        spyij = yij1-yi1j
        #sqxij = xij1-xi1j
        #sqyij = yi1j1-yij
        sqxija = abs(xij1-xi1j1)
        sqxijb = abs(xij-xi1j)
        sqyija = abs(yij1-yi1j1)
        sqyijb = abs(yij-yi1j)
    darea = spxij*spyij-(sqxija*sqyija+ sqxijb*sqyijb+(spxij-sqxija)*(spyij-sqyijb)+(spxij-sqxijb)*(spyij-sqyija))/2
    #darea = (abs(spxij*spyij)+abs(sqxij*sqyij))/2
    xmean = (xij+xij1)/2
    ymean = (yij+yij1)/2
    px1 = np.array([])
    py1 = np.array([])
    inp = 0
    #breakpoint()
    for i in range(divzd):
        if dim == 1:
            px0 = interpol_1d_np(saxisd,psaxisd,[xmean[i]])
        else:
            if type(psaxisd[i]) == int or len(saxisd[i]) <= 1:
                px0 = [0,np.zeros(divspn-1)]
            elif divspn == 0:
                px0 = [0,0]
            else:
                if inp == 0:
                    if gpu == 0:
                        px0 = interpol_1d_np([saxisd[i]],[saxisd[i],psaxisd[i]],[xmean[i]])
                    elif gpu == 1:
                        px0 = interpol_1d_cp([saxisd[i]],[saxisd[i],psaxisd[i]],[xmean[i]])
                elif inp == 1:
                    funp = interpolate.Rbf(saxisd[i],psaxisd[i],function='linear', smooth=0)
                    px0 = [0,funp(xmean[i])]
        px1 = np.append(px1,px0[1])
        py0 = interpol_1d_np([yaxd],[yaxd,pyaxd],[ymean[i]])
        py1 = np.append(py1,py0[1])
    pxmesh = px1.reshape(divzd,divspn-1)
    pymesh = py1.reshape(divzd,divspn-1)
    if dim == 1:
        pz_tmp = pxmesh*pymesh*darea/dt[0]
    elif dim == 2:
        #print(pxmesh.shape,pymesh.shape,darea.shape,dt_tn.shape,dt_tn.shape,divzn,divzn,divspn)
        #flag = np.array([[1 if xij[j][i] >= max(0,min_s[j]) and xij[j][i] <= max_s[j] and yij[j][i] >= ymin[0] and yij[j][i] <= min(0,ymax[0]) and \
        #                  np.sign(zf[0][j]) != np.sign(max_sx[j]) and np.sign(zf[1][j]) != np.sign(max_sy[j]) else 0 for i in range(divspn-1)]for j in range(divzn)])
        pz_tmp = pxmesh*pymesh*darea/(dtd.reshape(divzd,1)*np.ones((1,divspn-1)))
        #zi_tmp = zaxn.reshape(divzn,1)*np.ones((1,divspn-1))
        zi_tmp = abs(zaxd.reshape(divzd,1))*np.ones((1,divspn-1))
        #pz_tmp = flag*pz_tmp*abs(xij)/zi_tmp
        #pz_tmp = pz_tmp*abs(xij)/zi_tmp
        pz_tmp = pz_tmp*abs(xmean)/zi_tmp
    elif dim == 3:
        #flag = np.array([[1 if xij[j][i] >= max(0,min_s[j]) and xij[j][i] <= max_s[j] and yij[j][i] >= ymin[0] and yij[j][i] <= min(0,ymax[0]) and \
        #                  np.sign(zf[0][j]) != np.sign(max_sx[j]) and np.sign(zf[1][j]) != np.sign(max_sy[j]) and np.sign(zf[2][j]) != np.sign(max_sz[j]) \
        #                  else 0 for i in range(divspn-1)]for j in range(divzd)])
        pz_tmp = pxmesh*pymesh*darea/(dtd.reshape(divzd,1)*np.ones((1,divspn-1)))
        zi_tmp = zaxd.reshape(divzd,1)*np.ones((1,divspn-1))
        pz_tmp = pz_tmp*(xij/zi_tmp)**2
        #pz_tmp = flag*pz_tmp*(xij/zi_tmp)**2
    pz3 = np.sum(pz_tmp,axis=1)
    return pz3


def cal_divmerg(dim,flagq,pzq,divtq,npflag,calflag):
    #
    flag0,flag1,flag2,flag3 = flagq
    pz0,pz1,pz2,pz3 = pzq
    divta,divtb,divtc,divtd = divtq
    if flag0 == 1 and flag1 == 0 and flag2 == 0 and flag3 == 0:##
        if dim == 1:
            pz = pz0
        if dim == 2:
            pz = pz0.reshape(divta[1],divta[0])
        elif dim == 3:
            pz = pz0.reshape(divta[1],divta[0],divta[2])
    elif flag0 == 0 and flag1 == 0 and flag2 == 0 and flag3 == 1:##
        if dim == 1:
            pz = pz3
        if dim == 2:
            pz = pz3.reshape(divtd[1],divtd[0])
        elif dim == 3:
            pz = pz3.reshape(divtd[1],divtd[0],divtd[2])
    elif flag0 == 1 and flag1 == 0 and flag2 == 0 and flag3 == 1:##
        if calflag == 1:
            print('ゼロを含む分布で割った演算結果は保証されません')
        if dim == 1:
            pz = np.append(pz3,pz0)
        if dim == 2:
            if npflag == 1 or npflag == 3 or npflag == 7 or npflag == 9:
                pzmesh0 = pz0.reshape(divta[1],divta[0])
                pzmesh3 = pz3.reshape(divtd[1],divtd[0])
            if npflag == 1:#1つの象限
                pza = np.append(np.zeros((divta[1],divtd[0])),pzmesh0,axis=1)
                pzb = np.append(pzmesh3,np.zeros((divtd[1],divta[0])),axis=1)
                pz = np.append(pzb,pza,axis=0)
            elif npflag == 3:
                pza = np.append(pzmesh0,np.zeros((divta[1],divtd[0])),axis=1)
                pzb = np.append(np.zeros((divtd[1],divta[0])),pzmesh3,axis=1)
                pz = np.append(pzb,pza,axis=0)
            elif npflag == 7:
                pza = np.append(pzmesh3,np.zeros((divtd[1],divta[0])),axis=1)
                pzb = np.append(np.zeros((divta[1],divtd[0])),pzmesh0,axis=1)
                pz = np.append(pzb,pza,axis=0)
            elif npflag == 9:
                pza = np.append(np.zeros((divtd[1],divta[0])),pzmesh3,axis=1)
                pzb = np.append(pzmesh0,np.zeros((divta[1],divtd[0])),axis=1)
                pz = np.append(pzb,pza,axis=0)
            if npflag == 2 or npflag == 4 or npflag == 6 or npflag == 8:#2つの象限
                pza = pz0.reshape(divta[1],divta[0])
                pzb = pz3.reshape(divtd[1],divtd[0])
            if npflag == 2:
                pz = np.append(pzb,pza,axis=0)
            elif npflag == 4:
                pz = np.append(pzb,pza,axis=1)
            elif npflag == 6:
                pz = np.append(pza,pzb,axis=1)
            elif npflag == 8:
                pz = np.append(pza,pzb,axis=0)
                    
        elif dim == 3:
            #1つの象限
            if npflag == 1 or npflag == 3 or npflag == 6 or npflag == 8 or npflag == 18 or npflag == 20 or npflag == 24 or npflag == 26:
                pzmesh0 = pz0.reshape(divta[1],divta[0],divta[2])
                pzmesh3 = pz3.reshape(divtd[1],divtd[0],divtd[2])
                divt = [divtd[0]+divta[0]]
                #breakpoint()
                if npflag == 1:
                    #print(sum(pz0),sum(pz3))#9/27:pz0の確率値が10倍大きい、pz3の確率値は3倍大きい、原因調査必要
                    pza = np.append(np.zeros((divta[1],divtd[0],divta[2])),pzmesh0,axis=1)#x方向
                    pzb = np.append(np.zeros((divtd[1],divt[0],divta[2])),pza,axis=0)
                    pzc = np.append(pzmesh3,np.zeros((divtd[1],divta[0],divtd[2])),axis=1)
                    pzd = np.append(pzc,np.zeros((divta[1],divt[0],divtd[2])),axis=0)
                    pz = np.append(pzd,pzb,axis=2)
                elif npflag == 3:
                    pza = np.append(np.zeros((divta[1],divtd[0],divta[2])),pzmesh0,axis=1)
                    pzb = np.append(pza,np.zeros((divtd[1],divt[0],divta[2])),axis=0)
                    pzc = np.append(pzmesh3,np.zeros((divtd[1],divta[0],divtd[2])),axis=1)
                    pzd = np.append(np.zeros((divta[1],divt[0],divtd[2])),pzc,axis=0)
                    pz = np.append(pzd,pzb,axis=2)
                elif npflag == 6:
                    pza = np.append(np.zeros((divta[1],divtd[0],divta[2])),pzmesh0,axis=1)#yxz++-
                    pzb = np.append(np.zeros((divtd[1],divt[0],divta[2])),pza,axis=0)
                    pzc = np.append(pzmesh3,np.zeros((divtd[1],divta[0],divtd[2])),axis=1)#--+
                    pzd = np.append(pzc,np.zeros((divta[1],divt[0],divtd[2])),axis=0)
                    pz = np.append(pzb,pzd,axis=2)
                elif npflag == 8:
                    pza = np.append(np.zeros((divta[1],divtd[0],divta[2])),pzmesh0,axis=1)#-+-
                    pzb = np.append(pza,np.zeros((divtd[1],divt[0],divta[2])),axis=0)
                    pzc = np.append(pzmesh3,np.zeros((divtd[1],divta[0],divtd[2])),axis=1)#+-+
                    pzd = np.append(np.zeros((divta[1],divt[0],divtd[2])),pzc,axis=0)
                    pz = np.append(pzb,pzd,axis=2)
