def countminas(target):
    #配列のマイナス要素をカウントする
    minas=[1 for i in range(len(target)) if target[i]<0]
    print(sum(minas))


def bunpu_1d1kaisimu_fun(dt,time,acces,vel_x,flag2,acces0,vel0):#,accmax=[],velmax=[]):
    """
    以下にフィードバック制御を行う関数を記述
    
    """
    #以下は上記のベクトル表記
    #初期加速度に対して、初期加速度分布を最大として、比で制御を行う。
    acc = np.array(acces0)#初期加速度
    accmx = np.array(accmax)
    #ptn = 0
    #if ptn == 0:
        
    vel = np.array(vel_x)#フィードバック速度
    ptg = 15
    vtg = 0
    xtg = 100
    #flag = np.zeros((acc.shape))
    flag = ((pos<50+xtg)&(pos>-50+xtg))|(flag2==1)
    flag2 = flag.astype(int)#制御中のものが1
    flag1 = (~flag).astype(int)#非制御中のものが1
    cont00 = ((pos<3+xtg)&(pos>-3+xtg)&(vel<=1)&(vel>=-1)&(flag2==1))
    cont0 = cont00.astype(int)#制御中で目標で静止状態で加速度ゼロのものが1
    cont01 = (~cont00).astype(int)#
    cont1 = ((pos>=3+xtg)&(vel>-2)&(flag2==1)).astype(int)#目標より遠くて速度プラス→加速度マイナス（速度-2以上の場合）
    cont2 = ((pos<=-3+xtg)&(vel<2)&(flag2==1)).astype(int)#目標より近くて速度マイナス→加速度プラス（速度2以下の場合）
    cont3 = ((vel<-5)&(cont2==0)&(flag2==1)).astype(int)#目標より遠くて速度マイナスが大きい→加速度プラス（速度-5以下の場合）
    cont4 = ((vel>5)&(cont1==0)&(flag2==1)).astype(int)#目標より近くて速度プラスが大きい→加速度マイナス（速度5以上の場合）
    #cont_acc0 = acc*((flag==0).astype(int))+0.5*(vtg-vel)*(cont2-cont1)+0.1*(vtg-vel)*(cont3-cont4)
    #cont5 = (cont_acc0 >= acc) & (flag==1)
    #cont6 = (cont_acc0 <= -1*acc) & (flag==1)
    #cont_acc1 = acc*(cont5.astype(int)-cont6.astype(int))+cont_acc0*(~(cont5|cont6)).astype(int)
    #cont_acc = cont_acc1*cont0#+acc*flag1#目標で静止状態
    cont_acc = acc*flag1+accmx*(1-(cont1+cont2+cont3+cont4)-0.5*cont1-1.0*cont4+0.5*cont2+1.0*cont3)
    #if test3==1:
    #    breakpoint()
    return cont_acc,flag2
        

def bunpu_2d1kaisimu_fun(dt,time,acces,vel_x,flag,acces0,vel0):#,accmax=[],velmax=[]):
    """
    以下にフィードバック制御を行う関数を記述
    
    """
    #以下は上記のベクトル表記
    #初期加速度に対して、初期加速度分布を最大として、比で制御を行う。
    acc1 = acces0[0]#初期加速度
    acc2 = acces0[1]
    accmax1 = accmax[0]#加速度最大値
    accmax2 = accmax[1]
    vel1 = vel_x[0]#フィードバック速度
    vel2 = vel_x[1]
    ptn=1
    if ptn == 0:
        ptg = 15
        vtg1 = 0
        vtg2 = 0
        xtg1 = 100
        xtg2 = 100
        #flag = np.zeros((acc.shape))
        flag0 = ((pos1<50+xtg1)&(pos1>-50+xtg1))|(flag[0]==1)
        flag2 = flag0.astype(int)#制御中のものが1
        flag4 = (~flag0).astype(int)#非制御中のものが1
        cont00 = ((pos1<3+xtg1)&(pos1>-3+xtg1)&(vel1<=1)&(vel1>=-1)&(flag2==1))
        cont01 = cont00.astype(int)#制御中で目標で静止状態で加速度ゼロのものが1
        #cont01 = (~cont00).astype(int)#
        cont02 = ((pos1>=3+xtg1)&(vel1>-2)&(cont01==0)&(flag2==1)).astype(int)#目標より遠くて速度プラス→加速度マイナス（速度-2以上の場合）
        cont03 = ((pos1<=-3+xtg1)&(vel1<2)&(cont01==0)&(flag2==1)).astype(int)#目標より近くて速度マイナス→加速度プラス（速度2以下の場合）
        cont04 = ((vel1<-5)&(cont01==0)&(cont03==0)&(flag2==1)).astype(int)#目標より遠くて速度マイナスが大きい→加速度プラス（速度-5以下の場合）
        cont05 = ((vel1>5)&(cont01==0)&(cont02==0)&(flag2==1)).astype(int)#目標より近くて速度プラスが大きい→加速度マイナス（速度5以上の場合）
        #cont_acc1 = acc1*flag4+accmax1*(1-(cont01+cont02+cont03+cont04)-0.5*cont01-1.0*cont04+0.5*cont02+1.0*cont03)
        cont_acc1 = acc1*flag4+accmax1*(0.1*cont03+0.2*cont04-0.1*cont02-0.2*cont05)
        #
        flag1 = ((pos2<50+xtg2)&(pos2>-50+xtg2))|(flag[1]==1)
        flag3 = flag1.astype(int)#制御中のものが1
        flag5 = (~flag1).astype(int)#非制御中のものが1
        cont10 = ((pos2<3+xtg2)&(pos2>-3+xtg2)&(vel2<=1)&(vel2>=-1)&(flag3==1))
        cont11 = cont10.astype(int)#制御中で目標で静止状態で加速度ゼロのものが1
        #cont01 = (~cont00).astype(int)#
        cont12 = ((pos2>=3+xtg2)&(vel2>-2)&(cont11==0)&(flag3==1)).astype(int)#目標より遠くて速度プラス→加速度マイナス（速度-2以上の場合）
        cont13 = ((pos2<=-3+xtg2)&(vel2<2)&(cont11==0)&(flag3==1)).astype(int)#目標より近くて速度マイナス→加速度プラス（速度2以下の場合）
        cont14 = ((vel2<-5)&(cont11==0)&(cont13==0)&(flag3==1)).astype(int)#目標より遠くて速度マイナスが大きい→加速度プラス（速度-5以下の場合）
        cont15 = ((vel2>5)&(cont11==0)&(cont12==0)&(flag3==1)).astype(int)#目標より近くて速度プラスが大きい→加速度マイナス（速度5以上の場合）
        #cont_acc2 = acc2*flag5+accmax1*(1-(cont11+cont12+cont13+cont14)-0.5*cont11-1.0*cont14+0.5*cont12+1.0*cont13)
        cont_acc2 = acc2*flag5+accmax2*(0.1*cont13+0.2*cont14-0.1*cont12-0.2*cont15)
    elif ptn == 1:
        accg = -2
        cont_acc1 = np.zeros((acc1.shape))
        cont_acc2 = accg*np.ones((acc2.shape))
        flag2=flag[0]
        flag3=flag[1]
    #if outflag==0:
    #    breakpoint()
    return cont_acc1,cont_acc2,flag2,flag3
        
    
    
def bunpu_3d1kaisimu_fun(dt,time,acces,vel_x,flag,acces0,vel0):#,accmax=[],velmax=[]):
    """
    以下にフィードバック制御を行う関数を記述
    """
    #以下は上記のベクトル表記
    #初期加速度に対して、初期加速度分布を最大として、比で制御を行う。
    #初期加速時間
    initime = 2
    if time < initime:
        iniac = 1
    else:
        iniac = 0
    #ターゲット位置
    tgx = [40,40,80]
    #検出距離
    sdist = 20
    acc1 = acces0[0]#初期加速度
    acc2 = acces0[1]
    acc3 = acces0[2]
    accmax1 = accmax[0]#加速度最大値
    accmax2 = accmax[1]
    accmax3 = accmax[2]
    vel1 = vel_x[0]#フィードバック速度
    vel2 = vel_x[1]
    vel3 = vel_x[2]



    accg = -2
    cont_acc1 = np.zeros((acc1.shape))+iniac*acc1
    cont_acc2 = np.zeros((acc2.shape))+iniac*acc2
    cont_acc3 = accg*np.ones((acc3.shape))+iniac*acc3
    flag2=flag[0]
    flag3=flag[1]
    flag4=flag[2]
    #if outflag==0:
    #    breakpoint()
    return cont_acc1,cont_acc2,cont_acc3,flag2,flag3,flag4


