                            pacc = np.array(self.flatten[3]*adx).reshape(self.div[0]*self.div[1],1,1,1)*np.ones((1,other[0].div[0]*other[0].div[1],other[1].div[0]*other[1].div[1],other[2].div[0]*other[2].div[1]))
