                            ppot = np.array(other[2].flatten[3]*ydx).reshape(1,1,1,other[2].div[0]*other[2].div[1])*np.ones((self.div[0]*self.div[1],other[0].div[0]*other[0].div[1],other[1].div[0]*other[1].div[1],1))
                            pmat = pacc*pvel*ppos*ppot
