                    flag2 = np.zeros((self.div[0]*self.div[1]*self.div[2],other1.div[0]*other1.div[1]*other1.div[2],other2.div[0]*other2.div[1]*other2.div[2]))
                    flag3 = np.zeros((self.div[0]*self.div[1]*self.div[2],other1.div[0]*other1.div[1]*other1.div[2],other2.div[0]*other2.div[1]*other2.div[2]))
                    flag4 = np.zeros((self.div[0]*self.div[1]*self.div[2],other1.div[0]*other1.div[1]*other1.div[2],other2.div[0]*other2.div[1]*other2.div[2]))
