                    third.linemap.append([[0],self.div,self.dx,np.array(self.flatten[0]).reshape(1,self.div[0])*np.ones((other.linemap[0][3].shape[0],1)),\
                                          third.linemap[0][4]])
                    #np.array(self.flatten[1]).reshape(1,self.div[0])*np.ones((other.linemap[0][1][0],1))])
