        if self.dim!=0:
            dim=self.dim
        else:
            dim=len(x)-1
        if gpu==2:###cupy
           
            xp=self.para
            xm=self.mesh
        else:
            xp=self.para
            xm=self.mesh
        #print(len(xp[0]),len(xp[1]),len(xp[2]),xm[0].shape,xm[1].shape,xm[2].shape,xm[3].shape)
        dx=self.dx
        divn=self.div
