    def bunpu_twin_graph(self,other,filename='' ,contact=0,levels=5,linewidth=4,yscale=0,xscale=0,gpu=0,view = 0,svector = 0,svector2 = 0,ovector = 0,vpoint = 0,fs=14):
        #複数の分布をひとつのグラフに表示、分布の重なりがある場合（所定距離以内に存在する場合）の確率を求める
        #contact:重なりがあると判定する距離、スカラーとする
        #view 0:仰角 30°、方位角 -60°,1:仰角 30°、方位角 30°
        #contact>0 :距離がcontactより近い場合に接触として接触確率を求める
        #vector=配列の場合、そのベクトル位置を表示する,svector:selfを始点としたベクトル,ovector:otherを始点としたベクトル,vpointは表示するポイントを指定
        #fp = FontProperties(fname=r'C:\Windows\Fonts\msgothic.ttc',size=24)
        fp = FontProperties(fname=r'C:\Windows\Fonts\msgothic.ttc',size=fs)
        if filename!='':
            outgraphname=filename+'.png'
        x=self.flatten
        y=other.flatten
        if self.dim!=0:
            dim=self.dim
        else:
            dim=len(x)-1
        xp=self.para
        xm=self.mesh
        dx=self.dx
        divx=self.div
        yp=other.para
        ym=other.mesh
        dy=other.dx
        divy=other.div
        xmax = self.xmax
        xmin = self.xmin
        ymax = other.xmax
        ymin = other.xmin
        
        #tmin=[]
        #tmax=[]
        #exdivt=[]
        flag0 = []#1:重複部分が存在する
        #dtを計算して、重なりがそれより小さい場合は重複なしとする。
        #breakpoint()
        tmax=np.maximum(np.array(xmax),np.array(ymax)+contact)#全体の領域を求める5/8ymin,ymaxが空行列になっている、原因?
        tmin=np.minimum(np.array(xmin),np.array(ymin)-contact)
        dt0=np.minimum(np.array(dx),np.array(dy))
        exdivt=(contact/np.array(dt0)).astype(int)
        divt=np.array(divx)+np.array(divy)+exdivt
        dt=(tmax-tmin)/divt
        sbv = []#self base vector
        sv = []#svector
        sbv2 = []#self base vector
        sv2 = []#svector2
        obv = []#other base vector
        ov = []#ovextor
        #breakpoint()
        for i in range(dim):
            if xmax[i]<=ymin[i]-contact+dt[i] or xmin[i]>=ymax[i]+contact-dt[i]:#ひとつの次元でも成立すれば成立
                flag0.append(0)#重複がない
            elif xmin[i]>=ymax[i]-contact and xmax[i]<=ymin[i]+contact:#全ての次元が成立した場合だけ成立
                flag0.append(2)#100%重複している
            else:
                flag0.append(1)#重複が0%~100%
            if svector != 0:
                if type(svector) == bunpu:
                    sv.append(svector.linemap[0][i+3][vpoint[0]][vpoint[1]][vpoint[2]][vpoint[3]])
                    sbv.append(self.linemap[0][i+3][vpoint[0]][vpoint[1]][vpoint[2]][vpoint[3]])
                else:
                    sv.append(svector[i][vpoint[0]][vpoint[1]][vpoint[2]][vpoint[3]])
                    sbv.append(self.linemap[0][i+3][vpoint[0]][vpoint[1]][vpoint[2]][vpoint[3]])
            if svector2 != 0:
                if type(svector2) == bunpu:
                    sv2.append(svector2.linemap[0][i+3][vpoint[0]][vpoint[1]][vpoint[2]][vpoint[3]])
                    sbv2.append(self.linemap[0][i+3][vpoint[0]][vpoint[1]][vpoint[2]][vpoint[3]])
                else:
                    sv2.append(svector[i][vpoint[0]][vpoint[1]][vpoint[2]][vpoint[3]])
                    sbv2.append(self.linemap[0][i+3][vpoint[0]][vpoint[1]][vpoint[2]][vpoint[3]])
            if ovector != 0:
                if type(ovector) == bunpu:
                    ov.append(ovector.linemap[0][i+3][vpoint[0]][vpoint[1]][vpoint[2]][vpoint[3]])
                    obv.append(other.linemap[0][i+3][vpoint[0]][vpoint[1]][vpoint[2]][vpoint[3]])
                else:
                    ov.append(ovector[i][vpoint[0]][vpoint[1]][vpoint[2]][vpoint[3]])
                    obv.append(other.linemap[0][i+3][vpoint[0]][vpoint[1]][vpoint[2]][vpoint[3]])
            #これ以降やり直し（重複が0%~100%の場合だけ確率を計算するようにする）
            #tmax.append(max(xmax[i],ymax[i]+contact))#全体の領域を求める
            #tmin.append(min(xmin[i],ymin[i]-contact))
            #dt.append(max(dx[i],dy[i]))
            #divt.append(int((tmax[i]-tmin[i])/dt[i]))
            #divt.append(divx[i]+divy[i]+int(contact/(ymax[i]-ymin[i])))
            #dt.append((tmax[i]-tmin[i])/divt[i])
            #exdivt.append(int(contact/dt[i]))
        if dim==1:
            if flag0[0]==0:
                flag = 0#重複はない
            elif flag0[0]==2:
                flag = 2#100%重複している
            else:
                flag = 1#x0の重複を考慮
                
            fig=plt.figure(figsize=(14,7))
            ax = fig.add_subplot(111)
            if yscale != 0:
                ax.ylim(yscale)
            if xscale != 0:
                ax.xlim(xscale)
            #if contact>0:
            #    ax.plot(x[0], self.ruiseki[0], label="origin",linewidth = 4)
            #else:
            #breakpoint()
            if flag == 1 or flag == 2:
                t0=[]
                t1=[]
                y1=[]
                tpos=[]
                tpos1=[]
                tpos0=[]
                t=[np.linspace(tmin[0],tmax[0],divt[0])]
                for i in range(dim):
                    lastfg0 = 0
                    lastfg1 = 0
                    t0.append([])#xとy（contact含む）が重複する範囲でのtのパラメータ値配列
                    t1.append([])#t0の範囲をyの幅で広げた範囲（yの確率値を合計する範囲）
                    y1.append([])#yの範囲でtのパラメータ値の配列
