        if (ymin[0] >= 0 or (ymax[0] > 0 and ymin[0] < 0)) and  npflag != 5:#y,xが0点を跨がない(y>0)またはyが0点を跨ぐ、xが0点を跨がない
            flagza = [0 if (npflag == 1 and (zf[0][i] < 0 or zf[1][i] < 0)) or (npflag == 3 and (zf[0][i] > 0 or zf[1][i] < 0)) or (npflag == 7 and (zf[0][i] < 0 or zf[1][i] > 0)) \
                      or (npflag == 9 and (zf[0][i] > 0 or zf[1][i] > 0)) or (npflag == 2 and zf[1][i] < 0) or (npflag == 4 and zf[0][i] < 0) or (npflag == 6 and zf[0][i] > 0) \
                      or (npflag == 8 and zf[1][i] > 0) else 1 for i in range(divz)]
            saxisa = [[saxis[j][i] for i in range(len(saxis[j])) if saxis[j][i]>=0] for j in range(divz) if flagza[j] == 1]
            cntia = [i for i in range(divz) if flagza[i] == 1]
            saxisax = [[saxisx[j][i] for i in range(len(saxis[j])) if saxis[j][i]>=0] for j in range(divz) if flagza[j] == 1]
            saxisay = [[saxisy[j][i] for i in range(len(saxis[j])) if saxis[j][i]>=0] for j in range(divz) if flagza[j] == 1]
            zaxa = np.array([zi[i] for i in range(divz) if flagza[i] == 1])
            dt_ta = np.array([dt_t[i] for i in range(divz) if flagza[i] == 1])
            divsa = [divss[i] for i in range(divz) if flagza[i] == 1]
            if ymax[0] > 0 and ymin[0] < 0:#yが0点を跨ぐ、xが0点を跨がない場合だけ
                tiax = [ti[0][i] for i in range(divt[0]) if npflag == 2 or npflag == 8 or npflag == 5 or ((npflag == 1 or npflag == 7 or npflag == 4) and ti[0][i] >= 0) \
                        or ((npflag == 3 or npflag == 9 or npflag == 6) and ti[0][i] <= 0)]
                tiay = [ti[1][i] for i in range(divt[1]) if npflag == 4 or npflag == 5 or npflag == 6 or ((npflag == 1 or npflag == 2 or npflag == 3) and ti[1][i] >= 0) \
                        or ((npflag == 7 or npflag == 8 or npflag == 9) and ti[1][i] <= 0)]
                divta = [len(tiax),len(tiay)]
            else:
                divta = divt
            divza = zaxa.shape[0]
