                        plotx, ploty=np.mgrid[x0[0].min():x0[0].max()+dx[0]:dx[0]+hosei,x0[1].min():x0[1].max()+dx[1]:dx[1]+hosei]
                        ax.contour(plotx, ploty, plotdat, offset=min2, zdir='z', cmap='Greens')
