                        plotx, ploty=np.mgrid[min(t[0]):max(t[0])+dt[0]:dt[0]+hosei,min(t[1]):max(t[1])+dt[1]:dt[1]+hosei]
                        ax.contour(plotx, ploty, plotdat, offset=min2, zdir='z', cmap='Reds')
                        plotdat = np.sum(tp, axis=1) 
