                        ploty, plotz=np.mgrid[y0[1].min():y0[1].max()+dy[1]:dy[1]+hosei,y0[2].min():y0[2].max()+dy[2]:dy[2]+hosei]
                        ax.contour(plotdat, ploty, plotz, offset=min0, zdir='x', cmap='Blues')
                        
