    def bunpu_percent3(self, filename=[],pos=[], dirc=[], shw = 0, view = 0,fs = 14):
        """
        posを通って,dircの方向と直角の面よりdirec側の確率
        posとdircで複数のベクトル（面と方向）を指定して、複数の共通する領域の確率を求める
        現状２次元だけ
        
        """
        sha = len(pos)
        patn = 2
        dim=self.dim
        x0=self.para
        x1=self.flatten
        x=self.mesh
        xmax=self.xmax
        xmin=self.xmin
        menseki=0
        menseki0=0
        lastmen=0
        dx=self.dx
        div=self.div
        fp = FontProperties(fname=r'C:\Windows\Fonts\msgothic.ttc',size=fs)
        #fp = FontProperties(fname=r'C:\Windows\Fonts\msgothic.ttc',size=24)
        if filename==[]:
            filename=['output','unit']
        bihosei=1/10**10
        if dim==2:
            #pos1を通って、dircの方向と直角の面より、dirc方向の確率を求める
            #
            poslg=[]
            ldirc=[]
            for j in range(sha):
                ldirc.append((dirc[j][0]**2+dirc[j][1]**2)**0.5)#dircの長さ
                poslg.append((pos[j][0]*dirc[j][0]+pos[j][1]*dirc[j][1])/ldirc[j])#dirc方向の面の距離（原点からの）
                
            for i in range(len(x1[0])):#x1:self.flatten
                
                flag=0
                for j in range(sha):
                    xlg=(x1[0][i]*dirc[j][0]+x1[1][i]*dirc[j][1])/ldirc[j]#self.flattenの各位置のdirc上に垂線をおろした点の距離（原点からの）
                    if xlg>=poslg[j]:
                        flag += 1
                        
                #   dirc方向で面より遠方の場合            ふたつの面の間
                if flag >= sha:
                    menseki+=x1[2][i]*dx[0]*dx[1]#条件を満足する確率値合計
                    #inbunpu[0].append(((x1[0][i]-dirc[0]*xlg/(dirc[0]**2+dirc[1]**2))**2+(x1[1][i]-dirc[1]*xlg/(dirc[0]**2+dirc[1]**2))**2)**0.5)
                    #inbunpu[1].append(x1[2][i])#条件を満足する分布の確率の羅列
            if shw == 1:
                #poslg=[poslg1,poslg2]
                xmx=[]
                xmn=[]
                ymx=[]
                ymn=[]
                #if poslg1 == poslg2:
                #    cnt = 1
                #else:
                #    cnt = 2
                x1=[]
                x2=[]
                y1=[]
                y2=[]
                for i in range(sha):
                    #平面の座標を求める
                    if dirc[i][0] != 0:
                        x1.append((ldirc[i]**2+dirc[i][0]**2+dirc[i][1]**2)*(poslg[i]/(2*ldirc[i]*dirc[i][0]))-xmax[1]*dirc[i][1]/dirc[i][0])
                        x2.append((ldirc[i]**2+dirc[i][0]**2+dirc[i][1]**2)*(poslg[i]/(2*ldirc[i]*dirc[i][0]))-xmin[1]*dirc[i][1]/dirc[i][0])
                    else:
                        x1.append(poslg[i])
                        x2.append(poslg[i])
                    if dirc[i][1] != 0:
                        y1.append((ldirc[i]**2+dirc[i][0]**2+dirc[i][1]**2)*(poslg[i]/(2*ldirc[i]*dirc[i][1]))-xmax[0]*dirc[i][0]/dirc[i][1])
                        y2.append((ldirc[i]**2+dirc[i][0]**2+dirc[i][1]**2)*(poslg[i]/(2*ldirc[i]*dirc[i][1]))-xmin[0]*dirc[i][0]/dirc[i][1])
                    else:
                        y1.append(poslg[i])
                        y2.append(poslg[i])
                    #[xmx,ymx],[xmn,ymn]が分割ラインの座標
                    if x1[i] <= xmax[0] and x1[i] >= xmin[0]:
                        xmx.append(x1[i])
                        ymx.append(xmax[1])
                        if x2[i] <= xmax[0] and x2[i] >= xmin[0]:
                            xmn.append(x2[i])
                            ymn.append(xmin[1])
                        elif x2[i] > xmax[0]:
                            xmn.append(xmax[0])
                            ymn.append(y1[i])
                        elif x2[i] < xmin[0]:
                            xmn.append(xmin[0])
                            ymn.append(y2[i])
                            
                    elif x1[i] > xmax[0]:
                        xmx.append(xmax[0])
                        ymx.append(y1[i])
                        if y2[i] <= xmax[1] and y2[i] >= xmin[1]:
                            xmn.append(xmin[0])
                            ymn.append(y2[i])
                        elif y2[i] > xmax[1]:
                            xmn.append(x1[i])
                            ymn.append(xmax[1])
                        elif y2[i] < xmin[1]:
                            xmn.append(x2[i])
                            ymn.append(xmin[1])
                    elif x1[i] < xmin[0]:
                        xmx.append(xmin[0])
                        ymx.append(y2[i])
                        if y1[i] <= xmax[1] and y1[i] >= xmin[1]:
                            xmn.append(xmin[0])
                            ymn.append(y1[i])
                        elif y1[i] > xmax[1]:
                            xmn.append(x1[i])
                            ymn.append(xmax[1])
                        elif y1[i] < xmin[1]:
                            xmn.append(x2[i])
                            ymn.append(xmin[1])
                #矢印
                
                #if cnt == 1:
