        #patrn12=re.compile(r'^\s*(\S+)\s*\=\s*(\S+).(bunpu_simu_prb|bunpu_simu_graph)\((\S+),(\S+),(\S+),(\S+),(\S+),(\S+),?(\S*)\)')#時系列トータルの確率値を合計
        patrn12=re.compile(r'^\s*(\S+)\s*\=\s*(\S+).(bunpu_simu_prb|bunpu_simu_graph)\((\S+)\)')#時系列トータルの確率値を合計
        patrn13=re.compile(r'\s*(\S+)\s*\=\s*\'(\S+)\'')#文字を代入する
        patrn14=re.compile(r'\s*(\S+)\s*\=\s*([a-z]+[0-9]*)')#変数を代入する
        patrn15=re.compile(r'\s*(\S+)\s*\=\s*\[(\S*)\]')#リストを代入
        patrn16=re.compile(r'if\s*(\S+)\s*(==|<|<=|>|>=)\s*(\S+):')#条件判定→bunpufuncに追加
        patrn17=re.compile(r'^\s*(\S+)\s*\=\s*(\S+)(==|<|<=|>|>=)(\S+)')#代数の論理演算
        patrn18=re.compile(r'^\s*(\S+)\s*\=\s*\(*(\S+)\)*\.(astype)\(int\)')#
